//! The Radix system call interface: the twelve system calls, the methods
//! of every kind of object, their errors and the layouts of the memory
//! they share, generated by ridlc from `abi/*.ridl` when this crate builds
//! (ADR 0033).
//!
//! The kernel decodes arguments and encodes results with it; user programs
//! (through `libradix`) call the wrappers, which are generic over
//! [`Syscalls`] so that tests can stand in for the kernel. The C headers
//! and the man(2) pages come from the same files.

#![no_std]

include!(concat!(env!("OUT_DIR"), "/abi.rs"));

#[cfg(test)]
mod tests;
